examples.code:
Column {
    MonarchSwitchSettingsList(title = "Privacy") {
        MonarchSwitchSettingsRow(
            checked = share,
            onCheckedChange = { share = it },
            onSave = { delay(300) },
            label = "Share usage data",
            onStatusChange = { status = it },
        )
    }
    MonarchButton(
        text = "Done",
        onClick = {},
        variant = MonarchButtonVariant.Primary,
        enabled = status != MonarchSwitchSettingsStatus.Saving,
    )
}
